/**
 * Cynefin Decision Picker — tool-local actions.
 *
 * Category: Decision Frameworks (squad S13, Wave 4 — decision-CRUD tools)
 * Tool:     Snowden's Cynefin framework — classifies a problem into one of
 *           five domains (clear / complicated / complex / chaotic /
 *           confused) and recommends a domain-appropriate decision recipe.
 *
 * Agent surface: tool.cynefin.*
 * Backing CRUD : workspace.cynefin_item.* (auto-generated by
 *                defineCrudActions in src/lib/actions/workspace/index.ts).
 *
 * ─── CLASSIFIER + CRUD hybrid ────────────────────────────────────────
 * Cynefin is the union of two of the squad's earlier patterns:
 *   • CLASSIFIER (like eisenhower.ts) — given inputs about a problem,
 *     return a discrete domain label + a recommended action recipe.
 *   • CRUD-BACKED entity (like daci.ts) — items are persistent records
 *     in workspace.cynefin_items, mutated over a lifecycle.
 *
 * So we expose both:
 *   1. classify             — pure inference (no I/O). Maps signals
 *                             ("known-knowns", "urgent", …) to a domain
 *                             and the canonical recipe text used by the
 *                             in-app UI (cynefin-client.tsx:27).
 *   2. list_state           — read all items grouped by domain.
 *   3. classify_and_persist — classify (if signals given) or accept an
 *                             explicit domain, then create a row and
 *                             return its id. Single-call shortcut for
 *                             "log this problem to my Cynefin board".
 *   4. set_recommended_action — overwrite an item's recommendedAction
 *                             string. Useful when the agent has refined
 *                             the recipe beyond the default for that
 *                             domain (e.g. "Probe → Sense → Respond"
 *                             becomes a project-specific experiment plan).
 *
 * ─── ENTITY KIND ─────────────────────────────────────────────────────
 * The generic CRUD generator (defineCrudActions) takes
 * `toolId: "workspace.cynefin_item"` → kindFromToolId() →
 * `"workspace:cynefinItem"` (camelCase). This is what server-side
 * reads/writes through `server-store.ts` use, keeping the MCP path
 * byte-compatible with the generic surface.
 *
 * The BROWSER-side sync engine registers the same collection as
 * `"workspace:cynefinItem"` (see workspace-store.ts line 1343:
 * `registerCollection("cynefinItem", "cynefinItems")`) — the key under
 * which client rows live in localStorage / get pushed up the sync engine.
 * Both sides now agree on the camelCase kind, so MCP and browser writes
 * land on the same user_entities rows and round-trip cleanly. The
 * summarize-workspace intent reads the same camelCase key.
 * ─────────────────────────────────────────────────────────────────────
 */

import { z } from "zod";
import { registry } from "../registry";
import { useWorkspaceStore } from "@/lib/stores/workspace-store";
import { serverListEntities, serverGetEntity, serverUpsertEntity } from "../server-store";
import type { CynefinItem } from "@/lib/stores/workspace-types";

/** Server-side entity kind. Matches kindFromToolId("workspace.cynefin_item")
 *  so reads/writes here line up byte-for-byte with the auto-generated
 *  CRUD surface in workspace/index.ts and the browser sync key — both
 *  "workspace:cynefinItem". */
const KIND_CYNEFIN = "workspace:cynefinItem";

/** Closed enum of the five Cynefin domains, matching the literal union
 *  in workspace-types.ts:CynefinItem.domain verbatim. */
const DOMAINS = ["clear", "complicated", "complex", "chaotic", "confused"] as const;
type Domain = (typeof DOMAINS)[number];
const DomainSchema = z.enum(DOMAINS);

/** Canonical action recipe per domain. Strings match the recipes in
 *  cynefin-client.tsx:27 verbatim so an agent-classified item rendered
 *  in the UI shows the same recipe text as one classified via the UI. */
const RECIPE_BY_DOMAIN: Record<Domain, string> = {
  clear: "Sense → Categorise → Respond. Apply best practice.",
  complicated: "Sense → Analyse → Respond. Bring in experts.",
  complex: "Probe → Sense → Respond. Run safe-to-fail experiments.",
  chaotic: "Act → Sense → Respond. Stabilise first, then learn.",
  confused: "Break the problem into smaller domain-tagged pieces.",
};

function nowIso(): string {
  return new Date().toISOString();
}

/**
 * Pure rule: map an array of signal keywords to a Cynefin domain.
 *
 * Signal vocabulary (case-insensitive, lightly normalised):
 *   - "known-knowns" / "best practice" / "obvious"         → clear
 *   - "known-unknowns" / "expertise" / "analyse"           → complicated
 *   - "unknown-unknowns" / "emergent" / "experiment"       → complex
 *   - "urgent" / "chaos" / "crisis" / "act now"            → chaotic
 *   - "undecided" / "unclear" / "no agreement"             → confused
 *
 * Resolution rules (when multiple signals match different domains):
 *   1. chaotic wins outright (you stabilise first, classification later)
 *   2. complex beats complicated beats clear (most-novel wins among the
 *      three "stable" domains — the agent should default to humility
 *      when uncertain)
 *   3. confused is the explicit "no signal" fallback (no recognised
 *      keywords, or only "undecided"-class keywords)
 */
function classify(signals: string[]): {
  recommendedDomain: Domain;
  rationale: string;
  recommendedAction: string;
} {
  // Normalise so the agent doesn't have to think about case / whitespace
  // / punctuation when assembling the signals array.
  const normalised = signals.map((s) => s.toLowerCase().trim()).filter((s) => s.length > 0);

  let chaotic = false;
  let complex = false;
  let complicated = false;
  let clear = false;
  let confused = false;
  const matched: string[] = [];

  for (const s of normalised) {
    // Chaotic — checked first so the rationale message is accurate even
    // when other signals are also present.
    if (
      s.includes("urgent") ||
      s.includes("chaos") ||
      s.includes("crisis") ||
      s.includes("act now") ||
      s.includes("emergency") ||
      s.includes("fire")
    ) {
      chaotic = true;
      matched.push(s);
      continue;
    }
    // Complex — emergent, unknown-unknowns, experimental.
    if (
      s.includes("unknown-unknowns") ||
      s.includes("unknown unknowns") ||
      s.includes("emergent") ||
      s.includes("experiment") ||
      s.includes("probe")
    ) {
      complex = true;
      matched.push(s);
      continue;
    }
    // Complicated — known-unknowns, expertise required.
    if (
      s.includes("known-unknowns") ||
      s.includes("known unknowns") ||
      s.includes("expert") ||
      s.includes("analyse") ||
      s.includes("analyze")
    ) {
      complicated = true;
      matched.push(s);
      continue;
    }
    // Clear — known-knowns, best-practice.
    if (
      s.includes("known-knowns") ||
      s.includes("known knowns") ||
      s.includes("best practice") ||
      s.includes("obvious") ||
      s.includes("routine")
    ) {
      clear = true;
      matched.push(s);
      continue;
    }
    // Confused — explicit "we don't even know which bucket".
    if (
      s.includes("undecided") ||
      s.includes("unclear") ||
      s.includes("no agreement") ||
      s.includes("confused")
    ) {
      confused = true;
      matched.push(s);
      continue;
    }
    // Unrecognised signals are ignored, NOT errors — the agent may
    // include free-text signals like "the customer is angry" that don't
    // map to a domain cleanly. We fall through to the final resolution.
  }

  // Resolution order (priority high → low): chaotic > complex >
  // complicated > clear > confused. See function-header comment.
  let recommendedDomain: Domain;
  let rationaleSource: string;
  if (chaotic) {
    recommendedDomain = "chaotic";
    rationaleSource = "urgency / crisis signal — stabilise before classifying further";
  } else if (complex) {
    recommendedDomain = "complex";
    rationaleSource = "unknown-unknowns / emergent signal — needs probing not planning";
  } else if (complicated) {
    recommendedDomain = "complicated";
    rationaleSource = "known-unknowns signal — analysable with the right expertise";
  } else if (clear) {
    recommendedDomain = "clear";
    rationaleSource = "known-knowns / best-practice signal — apply established recipe";
  } else {
    // confused is the explicit fallback whether the user supplied it OR
    // simply didn't supply any recognised signals. Both cases want the
    // same "break it into smaller pieces" recipe.
    recommendedDomain = "confused";
    rationaleSource = confused
      ? "explicit confused signal — break into smaller domain-tagged pieces"
      : "no recognised signals — gather more information before classifying";
  }

  const matchedList = matched.length > 0 ? ` (matched: ${matched.join(", ")})` : "";
  return {
    recommendedDomain,
    rationale: `${rationaleSource}${matchedList}`,
    recommendedAction: RECIPE_BY_DOMAIN[recommendedDomain],
  };
}

// ──────── tool.cynefin.classify ────────
// Pure inference — given a title + signal keywords, return the
// recommended domain, a human-readable rationale, and the canonical
// action recipe. No persistence, no side effects, runs identically on
// server and client so no mcpHandler is needed.
registry.register({
  id: "tool.cynefin.classify",
  toolId: "tool.cynefin",
  name: "classify",
  category: "read",
  description:
    "Classify a problem into a Cynefin domain (clear / complicated / complex / chaotic / confused) from a list of signal keywords. Returns {recommendedDomain, rationale, recommendedAction}. Pure inference — no persistence. Signal vocabulary: 'known-knowns' → clear, 'known-unknowns' → complicated, 'unknown-unknowns' → complex, 'urgent'/'chaos' → chaotic, 'undecided' → confused. Priority order when multiple match: chaotic > complex > complicated > clear > confused.",
  paramsSchema: z.object({
    title: z.string().min(1).max(200).describe("Short label for the problem being classified"),
    signals: z
      .array(z.string())
      .describe("Keywords describing what's known/unknown about the problem. Case-insensitive."),
  }),
  handler: async (params) => {
    return classify(params.signals);
  },
  // No mcpHandler — pure compute runs identically on server and client.
});

// ──────── tool.cynefin.list_state ────────
// Snapshot grouped by domain. Cynefin's natural read shape is "what's
// in each domain?" — the UI renders five buckets, and the agent's
// opening question for the tool is almost always "where do my problems
// currently sit?". Returning them pre-grouped avoids a reduce on the
// agent's end.
registry.register({
  id: "tool.cynefin.list_state",
  toolId: "tool.cynefin",
  name: "list_state",
  category: "read",
  description:
    "List all Cynefin items in the workspace, grouped by domain. Returns {clear: CynefinItem[], complicated: CynefinItem[], complex: CynefinItem[], chaotic: CynefinItem[], confused: CynefinItem[], total: number}.",
  paramsSchema: z.object({}),
  handler: async () => {
    const items = useWorkspaceStore.getState().cynefinItems ?? [];
    return groupByDomain(items);
  },
  mcpHandler: async (_params, ctx) => {
    const items = await serverListEntities<CynefinItem>(ctx.userId, KIND_CYNEFIN);
    return groupByDomain(items);
  },
});

/** Bucket items by their persisted `domain`. Items with an unrecognised
 *  domain (e.g. legacy "simple" from pre-2014 Cynefin) fall back to
 *  "confused" — same defensive coercion the client does at
 *  cynefin-client.tsx:116 so the agent and UI agree on bucketing of
 *  malformed rows. */
function groupByDomain(items: CynefinItem[]): {
  clear: CynefinItem[];
  complicated: CynefinItem[];
  complex: CynefinItem[];
  chaotic: CynefinItem[];
  confused: CynefinItem[];
  total: number;
} {
  const grouped: Record<Domain, CynefinItem[]> = {
    clear: [],
    complicated: [],
    complex: [],
    chaotic: [],
    confused: [],
  };
  for (const it of items) {
    const d: Domain = DOMAINS.includes(it.domain as Domain) ? (it.domain as Domain) : "confused";
    grouped[d].push(it);
  }
  return { ...grouped, total: items.length };
}

// ──────── tool.cynefin.classify_and_persist ────────
// One-call shortcut: classify (if `signals` were given) OR accept an
// explicit `domain`, build a CynefinItem, and save it. The agent's
// natural phrasing is "log this problem as complex" or "this is
// urgent — figure out the domain and add it to my Cynefin board"; both
// resolve through this single action.
//
// If both `domain` and `signals` are supplied, the explicit `domain`
// wins (caller already decided). If neither is supplied, Zod rejects
// (see refine() at the schema level).
registry.register({
  id: "tool.cynefin.classify_and_persist",
  toolId: "tool.cynefin",
  name: "classify_and_persist",
  category: "write",
  requiresConfirmation: false,
  description:
    "Persist a new Cynefin item to the workspace. Supply either an explicit `domain` (the caller has already classified) OR a `signals` array (this action runs tool.cynefin.classify under the hood). If both are supplied, `domain` wins. The recommendedAction recipe is derived from the final domain unless explicitly overridden. Returns {id, domain, recommendedAction}.",
  paramsSchema: z
    .object({
      title: z.string().min(1).max(200),
      domain: DomainSchema.optional().describe(
        "Explicit Cynefin domain — overrides classification when both this and `signals` are supplied"
      ),
      signals: z
        .array(z.string())
        .optional()
        .describe(
          "Signal keywords to auto-classify. Ignored when `domain` is supplied. See tool.cynefin.classify for vocabulary."
        ),
      rationale: z
        .string()
        .max(2000)
        .optional()
        .describe("Why this domain? Overrides the auto-generated rationale when present."),
      recommendedAction: z
        .string()
        .max(2000)
        .optional()
        .describe("Custom action recipe. Overrides the canonical per-domain recipe when present."),
    })
    .refine((p) => p.domain !== undefined || (p.signals && p.signals.length > 0), {
      message: "Must supply either an explicit `domain` or a non-empty `signals` array.",
    }),
  handler: async (params) => {
    const item = buildItem(params);
    useWorkspaceStore.getState().upsertCynefinItem(item);
    return {
      id: item.id,
      domain: item.domain,
      recommendedAction: item.recommendedAction,
    };
  },
  mcpHandler: async (params, ctx) => {
    const item = buildItem(params);
    await serverUpsertEntity<CynefinItem>(ctx.userId, KIND_CYNEFIN, item);
    return {
      id: item.id,
      domain: item.domain,
      recommendedAction: item.recommendedAction,
    };
  },
});

/** Resolve a classify_and_persist params object into a fully-formed
 *  CynefinItem. Centralises the "explicit domain wins; otherwise
 *  classify from signals; rationale/recommendedAction default to the
 *  derived values but can be overridden" precedence logic so the
 *  browser-path and MCP-path handlers can't drift. */
function buildItem(params: {
  title: string;
  domain?: Domain;
  signals?: string[];
  rationale?: string;
  recommendedAction?: string;
}): CynefinItem {
  let domain: Domain;
  let derivedRationale: string;
  let derivedAction: string;

  if (params.domain) {
    // Explicit domain — skip the classifier. Rationale defaults to a
    // short marker so list_state consumers don't see an empty field.
    domain = params.domain;
    derivedRationale = "explicit domain provided by caller";
    derivedAction = RECIPE_BY_DOMAIN[domain];
  } else {
    // Schema-level refine guarantees signals is non-empty here.
    const classified = classify(params.signals ?? []);
    domain = classified.recommendedDomain;
    derivedRationale = classified.rationale;
    derivedAction = classified.recommendedAction;
  }

  return {
    id: `cynefin_${Math.random().toString(36).slice(2, 10)}`,
    title: params.title.slice(0, 200),
    domain,
    rationale: params.rationale ?? derivedRationale,
    recommendedAction: params.recommendedAction ?? derivedAction,
    loggedAt: nowIso(),
  };
}

// ──────── tool.cynefin.set_recommended_action ────────
// Convenience over workspace.cynefin_item.update for the single field
// the agent most often refines after initial classification. The
// per-domain default ("Probe → Sense → Respond") is a starting point;
// project-specific recipes ("Probe by spiking the auth flow this
// sprint, then…") replace it via this action without the agent
// marshalling a {patch: {recommendedAction: …}} payload.
//
// requiresConfirmation:false because it's a single-field overwrite on
// an existing record — no destruction, no cascading changes.
registry.register({
  id: "tool.cynefin.set_recommended_action",
  toolId: "tool.cynefin",
  name: "set_recommended_action",
  category: "write",
  requiresConfirmation: false,
  description:
    "Overwrite the recommendedAction field on an existing Cynefin item. Useful when the agent has refined the per-domain default recipe into a project-specific plan. Returns {updated: false} when the id is unknown.",
  paramsSchema: z.object({
    id: z.string(),
    recommendedAction: z.string().min(1).max(2000),
  }),
  handler: async (params) => {
    const items = useWorkspaceStore.getState().cynefinItems ?? [];
    const current = items.find((c) => c.id === params.id);
    if (!current) return { updated: false };
    useWorkspaceStore
      .getState()
      .upsertCynefinItem({ ...current, recommendedAction: params.recommendedAction });
    return { updated: true };
  },
  mcpHandler: async (params, ctx) => {
    const current = await serverGetEntity<CynefinItem>(ctx.userId, KIND_CYNEFIN, params.id);
    if (!current) return { updated: false };
    await serverUpsertEntity<CynefinItem>(ctx.userId, KIND_CYNEFIN, {
      ...current,
      recommendedAction: params.recommendedAction,
    });
    return { updated: true };
  },
});
